    // ============ BGM 播放系统 ============
    const bgmData = ""; // ← ffmpeg 压缩后替换

    let bgmLoaded = false;
    function initBGM() {
      const a = document.getElementById("bgmAudio");
      if (bgmData.startsWith("BGMDATA_")) return; // 占位符未替换
      a.src = "data:audio/mpeg;base64," + bgmData;
      a.volume = 0.35;
      a.load();
      bgmLoaded = true;
    }

    function toggleBGM() {
      if (!bgmLoaded) initBGM();
      const a = document.getElementById("bgmAudio");
      const btn = document.getElementById("bgmBtn");
      if (a.paused) {
        a.play().then(() => {
          btn.classList.add("on");
          btn.querySelector(".bgm-icon").textContent = "🎵";
        }).catch(() => {});
      } else {
        a.pause();
        btn.classList.remove("on");
        btn.querySelector(".bgm-icon").textContent = "🔇";
      }
    }

    // 用户首次交互后自动播放（绕过浏览器自动播放限制）
    let _bgmAutoOnce = false;
    function _bgmAutoPlay() {
      if (_bgmAutoOnce || !bgmLoaded) return;
      _bgmAutoOnce = true;
      const a = document.getElementById("bgmAudio");
      const btn = document.getElementById("bgmBtn");
      a.play().then(() => {
        btn.classList.add("on");
        btn.querySelector(".bgm-icon").textContent = "🎵";
      }).catch(() => {});
    }
    document.addEventListener("click", _bgmAutoPlay, { once: false });
    document.addEventListener("pointerdown", _bgmAutoPlay, { once: false });

